#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe ftp-read-a-files-size-and-date. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'written after the time was set' > marker.txt
cat > keep-time.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Downloads the URL in the first argument with the curl options after it, then says
# whether the local copy is older than marker.txt, a file written a moment ago.
url=$1; shift
curl -s "$@" -o copy.txt "$url" || exit
if [ copy.txt -ot marker.txt ]; then echo "copy is older than marker.txt"; else echo "copy is new"; fi
EOF
touch -t 202401021504.05 site/hello.txt
surl --directory site --allow-anonymous ftp://127.0.0.1:8080/ &
sleep 1
curl -I ftp://127.0.0.1:8080/hello.txt
kill $(jobs -p)
